struct AuditInner {
    path: PathBuf,
    active_date: NaiveDate,
}

struct AuditLog {
    dir: PathBuf,
    inner: Mutex<AuditInner>,
}

impl AuditLog {
    fn new(runtime_dir: &Path) -> Result<Self> {
        Self::new_at(runtime_dir, Utc::now())
    }

    fn new_at(runtime_dir: &Path, now: DateTime<Utc>) -> Result<Self> {
        let audit_dir = runtime_dir.join("audit");
        fs::create_dir_all(&audit_dir).context("failed to create audit directory")?;
        let active_date = now.date_naive();
        Ok(Self {
            dir: audit_dir.clone(),
            inner: Mutex::new(AuditInner {
                path: audit_dir.join(audit_file_name(active_date)),
                active_date,
            }),
        })
    }

    fn path(&self) -> PathBuf {
        self.inner.lock().path.clone()
    }

    fn append(&self, event: &RuntimeEvent) -> Result<()> {
        self.append_at(event, Utc::now())
    }

    fn append_at(&self, event: &RuntimeEvent, now: DateTime<Utc>) -> Result<()> {
        let today = now.date_naive();
        let rotated = {
            let mut inner = self.inner.lock();
            let rotated = if today != inner.active_date {
                inner.active_date = today;
                inner.path = self.dir.join(audit_file_name(today));
                true
            } else {
                false
            };

            let mut file = OpenOptions::new()
                .create(true)
                .append(true)
                .open(&inner.path)
                .with_context(|| format!("failed to open audit log at {}", inner.path.display()))?;
            let payload =
                serde_json::to_string(event).context("failed to serialize audit event")?;
            writeln!(file, "{payload}").context("failed to append audit event")?;
            rotated
        };

        if rotated {
            self.sweep_and_gzip_stale(today);
        }

        Ok(())
    }

    fn sweep_and_gzip_stale(&self, active_date: NaiveDate) {
        let entries = match fs::read_dir(&self.dir) {
            Ok(entries) => entries,
            Err(error) => {
                eprintln!(
                    "audit rotation: failed to scan stale logs in {}: {error}",
                    self.dir.display()
                );
                return;
            }
        };

        for entry in entries.flatten() {
            let path = entry.path();
            let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
                continue;
            };
            let Some(date) = parse_audit_file_date(file_name) else {
                continue;
            };
            if date >= active_date {
                continue;
            }

            if let Err(error) = gzip_and_remove(&path) {
                eprintln!(
                    "audit rotation: gzip failed for {} - leaving plain file in place: {error:#}",
                    path.display()
                );
            }
        }
    }
}

#[derive(Clone)]
struct RunningSession {
    pty: Option<Arc<dyn PtySession>>,
    input_gate: Arc<RunInputGate>,
    output_close_in_flight: Arc<AtomicBool>,
    last_resize: Option<(u16, u16)>,
    /// Per-run identity proof handed to the pane as `PRIM1_PANE_SECRET`.
    pane_secret: Option<String>,
    /// v3 W4 S2: an App Server member's way to its owner's observer.
    app_server: Option<codex_app_server::Dispatcher>,
}

impl RunningSession {
    fn new(pty: Option<Arc<dyn PtySession>>) -> Self {
        Self {
            pty,
            input_gate: Arc::new(RunInputGate::new()),
            output_close_in_flight: Arc::new(AtomicBool::new(false)),
            last_resize: None,
            pane_secret: None,
            app_server: None,
        }
    }

    fn with_pane_secret(mut self, pane_secret: Option<String>) -> Self {
        self.pane_secret = pane_secret;
        self
    }

    fn with_app_server(mut self, app_server: Option<codex_app_server::Dispatcher>) -> Self {
        self.app_server = app_server;
        self
    }

    fn close_input(&self) {
        self.input_gate.close();
    }
}

struct RunInputGate {
    state: Mutex<RunInputState>,
    ready: Condvar,
    // Separate from ticket state: operator/pane raw input announces intent
    // before waiting behind a wake. Never hold this while waiting for a ticket.
    room_input_activity: Mutex<room_composer::InputActivity>,
    // One room wake per current run, independent of feed/dedup retention.
    // A durable Pending with no recorded outcome keeps this run held.
    room_wake_pending: AtomicBool,
    room_wake_claim: Mutex<Option<(shared_types::MessageId, shared_types::RoomFeedCursor)>>,
    // D9 step 5: operator input admitted but not yet terminated (written or
    // failed). Lock-free so admission never waits on a wake; a room wake is
    // held at planning, before its paste and before its Enter while this is
    // non-zero (Codex review of 34cb00c).
    operator_inputs_pending: AtomicUsize,
}

impl RunInputGate {
    fn queued_operator_input_blocks_wake(&self) -> bool {
        self.operator_inputs_pending.load(Ordering::SeqCst) > 0
    }
}

struct RunInputState {
    accepting: bool,
    active: bool,
    cancellation_barrier: bool,
    next_ticket: u64,
    queue: VecDeque<u64>,
}

struct RunInputPermit<'a> {
    gate: &'a RunInputGate,
    control: Option<&'a InputWriteControl>,
}

const INPUT_WRITE_PENDING: u8 = 0;
const INPUT_WRITE_ACTIVE: u8 = 1;
const INPUT_WRITE_CANCELLED_BEFORE_START: u8 = 2;
const INPUT_WRITE_CANCELLING: u8 = 3;
const INPUT_WRITE_FINISHED: u8 = 4;
const INPUT_WRITE_FINISHED_AFTER_CANCEL: u8 = 5;

struct InputWriteControl {
    state: AtomicU8,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum InputCancelDisposition {
    BeforeStart,
    InFlight,
    Finished,
}

struct RunEventPublishState {
    next_sequence: Option<u64>,
    pending: BTreeMap<u64, RuntimeEvent>,
    draining: bool,
}

impl RunEventPublishState {
    fn new(next_sequence: u64) -> Self {
        Self {
            next_sequence: Some(next_sequence),
            pending: BTreeMap::new(),
            draining: false,
        }
    }
}

impl RunInputGate {
    fn new() -> Self {
        Self {
            state: Mutex::new(RunInputState {
                accepting: true,
                active: false,
                cancellation_barrier: false,
                next_ticket: 0,
                queue: VecDeque::new(),
            }),
            ready: Condvar::new(),
            room_input_activity: Mutex::new(room_composer::InputActivity::default()),
            room_wake_pending: AtomicBool::new(false),
            operator_inputs_pending: AtomicUsize::new(0),
            room_wake_claim: Mutex::new(None),
        }
    }

    fn begin_write<'a>(
        &'a self,
        control: Option<&'a InputWriteControl>,
    ) -> Result<RunInputPermit<'a>> {
        let mut state = self.state.lock();
        if !state.accepting {
            return Err(anyhow!("run is closed for input"));
        }
        let ticket = state.next_ticket;
        state.next_ticket = state
            .next_ticket
            .checked_add(1)
            .ok_or_else(|| anyhow!("run input ticket space exhausted"))?;
        state.queue.push_back(ticket);

        loop {
            if control.is_some_and(InputWriteControl::cancelled_before_start) {
                if let Some(position) = state.queue.iter().position(|queued| *queued == ticket) {
                    state.queue.remove(position);
                }
                self.ready.notify_all();
                return Err(anyhow!("input write cancelled before PTY input began"));
            }
            if !state.accepting {
                if let Some(position) = state.queue.iter().position(|queued| *queued == ticket) {
                    state.queue.remove(position);
                }
                self.ready.notify_all();
                return Err(anyhow!("run is closed for input"));
            }
            if !state.active && !state.cancellation_barrier && state.queue.front() == Some(&ticket)
            {
                state.queue.pop_front();
                state.active = true;
                return Ok(RunInputPermit {
                    gate: self,
                    control,
                });
            }
            self.ready.wait(&mut state);
        }
    }

    fn close(&self) {
        let mut state = self.state.lock();
        state.accepting = false;
        self.ready.notify_all();
    }

    fn is_accepting(&self) -> bool {
        self.state.lock().accepting
    }

    fn wake_waiters(&self) {
        self.ready.notify_all();
    }

    fn begin_cancellation_barrier(&self) {
        self.state.lock().cancellation_barrier = true;
    }

    fn end_cancellation_barrier(&self) {
        let mut state = self.state.lock();
        state.cancellation_barrier = false;
        self.ready.notify_all();
    }

    fn wait_until_idle_timeout(&self, timeout: Duration) -> bool {
        let deadline = Instant::now() + timeout;
        let mut state = self.state.lock();
        while state.active || !state.queue.is_empty() {
            let now = Instant::now();
            if now >= deadline {
                return false;
            }
            self.ready.wait_for(&mut state, deadline - now);
        }
        true
    }

    #[cfg(test)]
    fn queued_writes(&self) -> usize {
        self.state.lock().queue.len()
    }
}

struct TerminationAttempt {
    kill_error: Option<String>,
    exit_status: Option<PtyExitStatus>,
    exit_poll_error: Option<String>,
    input_idle: bool,
}

enum BoundedTerminationAttempt {
    Completed(TerminationAttempt),
    TimedOut(mpsc::Receiver<TerminationAttempt>),
}

fn begin_termination_attempt(
    pty: Arc<dyn PtySession>,
    input_gate: Arc<RunInputGate>,
    deadline: Instant,
) -> mpsc::Receiver<TerminationAttempt> {
    let (tx, rx) = mpsc::sync_channel(1);
    thread::spawn(move || {
        let kill_error = pty.kill().err().map(|error| error.to_string());
        let (exit_status, exit_poll_error) = match pty.try_wait() {
            Ok(status) => (status, None),
            Err(error) => (None, Some(error.to_string())),
        };
        let input_idle = kill_error.is_none()
            && input_gate
                .wait_until_idle_timeout(deadline.saturating_duration_since(Instant::now()));
        let _ = tx.send(TerminationAttempt {
            kill_error,
            exit_status,
            exit_poll_error,
            input_idle,
        });
    });
    rx
}

fn terminate_running_session_bounded(
    pty: Arc<dyn PtySession>,
    input_gate: Arc<RunInputGate>,
    timeout: Duration,
) -> BoundedTerminationAttempt {
    let deadline = Instant::now() + timeout;
    let rx = begin_termination_attempt(pty, input_gate, deadline);
    match rx.recv_timeout(timeout) {
        Ok(attempt) => BoundedTerminationAttempt::Completed(attempt),
        Err(_) => BoundedTerminationAttempt::TimedOut(rx),
    }
}

impl InputWriteControl {
    fn new() -> Self {
        Self {
            state: AtomicU8::new(INPUT_WRITE_PENDING),
        }
    }

    fn begin_pty_write(&self) -> Result<()> {
        match self.state.compare_exchange(
            INPUT_WRITE_PENDING,
            INPUT_WRITE_ACTIVE,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => Ok(()),
            Err(INPUT_WRITE_CANCELLED_BEFORE_START) => {
                Err(anyhow!("input write cancelled before PTY input began"))
            }
            Err(state) => Err(anyhow!(
                "input write entered an invalid cancellation state {state}"
            )),
        }
    }

    fn finish(&self) {
        loop {
            let state = self.state.load(Ordering::Acquire);
            let finished = match state {
                INPUT_WRITE_ACTIVE => INPUT_WRITE_FINISHED,
                INPUT_WRITE_CANCELLING => INPUT_WRITE_FINISHED_AFTER_CANCEL,
                INPUT_WRITE_CANCELLED_BEFORE_START => INPUT_WRITE_FINISHED_AFTER_CANCEL,
                INPUT_WRITE_FINISHED | INPUT_WRITE_FINISHED_AFTER_CANCEL => return,
                other => panic!("invalid input-write completion state {other}"),
            };
            if self
                .state
                .compare_exchange(state, finished, Ordering::AcqRel, Ordering::Acquire)
                .is_ok()
            {
                return;
            }
        }
    }

    fn request_cancel(&self) -> InputCancelDisposition {
        loop {
            let state = self.state.load(Ordering::Acquire);
            match state {
                INPUT_WRITE_PENDING => {
                    if self
                        .state
                        .compare_exchange(
                            INPUT_WRITE_PENDING,
                            INPUT_WRITE_CANCELLED_BEFORE_START,
                            Ordering::AcqRel,
                            Ordering::Acquire,
                        )
                        .is_ok()
                    {
                        return InputCancelDisposition::BeforeStart;
                    }
                }
                INPUT_WRITE_ACTIVE => {
                    if self
                        .state
                        .compare_exchange(
                            INPUT_WRITE_ACTIVE,
                            INPUT_WRITE_CANCELLING,
                            Ordering::AcqRel,
                            Ordering::Acquire,
                        )
                        .is_ok()
                    {
                        return InputCancelDisposition::InFlight;
                    }
                }
                INPUT_WRITE_CANCELLED_BEFORE_START => {
                    return InputCancelDisposition::BeforeStart;
                }
                INPUT_WRITE_CANCELLING => return InputCancelDisposition::InFlight,
                INPUT_WRITE_FINISHED | INPUT_WRITE_FINISHED_AFTER_CANCEL => {
                    return InputCancelDisposition::Finished;
                }
                other => panic!("invalid input-write cancellation state {other}"),
            }
        }
    }

    fn cancelled_before_start(&self) -> bool {
        self.state.load(Ordering::Acquire) == INPUT_WRITE_CANCELLED_BEFORE_START
    }

    fn cancellation_was_requested(&self) -> bool {
        matches!(
            self.state.load(Ordering::Acquire),
            INPUT_WRITE_CANCELLING | INPUT_WRITE_FINISHED_AFTER_CANCEL
        )
    }
}

impl Drop for RunInputPermit<'_> {
    fn drop(&mut self) {
        let mut state = self.gate.state.lock();
        if self
            .control
            .is_some_and(InputWriteControl::cancellation_was_requested)
        {
            state.cancellation_barrier = true;
        }
        state.active = false;
        self.gate.ready.notify_all();
    }
}

struct BackgroundRuntime(Option<tokio::runtime::Runtime>);

impl BackgroundRuntime {
    fn new(runtime: tokio::runtime::Runtime) -> Self {
        Self(Some(runtime))
    }

    fn spawn<Future>(&self, future: Future) -> tokio::task::JoinHandle<Future::Output>
    where
        Future: std::future::Future + Send + 'static,
        Future::Output: Send + 'static,
    {
        self.0
            .as_ref()
            .expect("background runtime unavailable during supervisor lifetime")
            .spawn(future)
    }
}

impl Drop for BackgroundRuntime {
    fn drop(&mut self) {
        let Some(runtime) = self.0.take() else {
            return;
        };
        if tokio::runtime::Handle::try_current().is_ok() {
            runtime.shutdown_background();
        } else {
            drop(runtime);
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StopIntentKind {
    Operator,
    Restart,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct StopIntent {
    generation: SessionGeneration,
    kind: StopIntentKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LifecycleOperation {
    generation: SessionGeneration,
    kind: StopIntentKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SpawnReservation {
    generation: SessionGeneration,
    run_id: Uuid,
}

enum RunRetirementCause {
    OutputClosed,
    PtyError(String),
    Liveness {
        final_state: LifecycleState,
        fallback_reason: SessionExitReason,
        detail: String,
        /// Set only when the exit is inferred from terminal evidence (an Exited
        /// work state with no agent process yet observed): the run-event
        /// sequence that inference saw. The retirement claim requires it to be
        /// unchanged, so fresh same-run output in between cancels the claim.
        inferred_at_sequence: Option<u64>,
    },
    /// F2: the agent's exit was proven, but processes it started still held
    /// the terminal after the drain grace, so the run could never reach output
    /// EOF. `root_status` is a native agent root's status read before the scope
    /// kill; `None` means the root was a wrapper or shim, still running or
    /// unreadable, and the agent's own exit status is then unknown, never the
    /// killed root's.
    DrainExpired {
        root_status: Option<PtyExitStatus>,
        detail: String,
    },
}

impl RunRetirementCause {
    fn final_state(&self) -> LifecycleState {
        match self {
            Self::OutputClosed | Self::DrainExpired { .. } => LifecycleState::Closed,
            Self::PtyError(_) => LifecycleState::Failed,
            Self::Liveness { final_state, .. } => *final_state,
        }
    }

    fn detail(&self) -> &str {
        match self {
            Self::OutputClosed => "session output closed",
            Self::PtyError(error) => error,
            Self::Liveness { detail, .. } | Self::DrainExpired { detail, .. } => detail,
        }
    }
}

struct QuiesceTimer {
    generation: SessionGeneration,
    run_id: Uuid,
    /// Stable identity of this worker, not the latest output/deadline.
    armed_at: Instant,
    handle: tokio::task::JoinHandle<()>,
}

struct SessionSlot {
    session_id: Uuid,
    definition: SessionDefinition,
    launch_choices: SessionLaunchChoices,
    last_launch: Option<SessionLaunchRecord>,
    qualified_working_directory: Option<QualifiedWorkingDirectory>,
    state: LifecycleState,
    work_state: WorkState,
    work_state_observed: bool,
    /// The state immediately preceding Exited, captured under slots rather than
    /// inferred from a potentially delayed persistence callback.
    work_state_before_exit: Option<WorkState>,
    /// Display projection only. The catalog token remains launch authority.
    crash_respawn_waiting: bool,
    /// v3: the one automatic fresh start after Claude found no conversation to
    /// resume was already spent in this process; a second refusal stops.
    claude_auto_fresh_attempted: bool,
    /// Exact crash start admitted before upgrade closing interrupted it. Used
    /// only to release its process-free Starting state when admission reopens.
    crash_start_admission: Option<(Uuid, SessionGeneration)>,
    /// Run-event sequence of the latest committed work-state transition. Its
    /// side effects (stall watchdog) apply only while it is still the latest,
    /// so a delayed older transition cannot undo a newer one, even when the
    /// states repeat (Idle, Blocked, Idle).
    last_work_state_sequence: Option<u64>,
    work_detail: Option<String>,
    /// v3 W2 #4: this run's advisory-notice match count when its notice
    /// expired, and the wall time it went quiet. It holds until a fresh
    /// matched notice (the count moves), another state or a new run; other
    /// output never makes it current again (Reviewer ded940b6).
    advisory_expired_at: Option<(u64, String)>,
    /// v3 W2 #4: how many times this run's driver has reported an advisory
    /// notice. Codex reports one only from fresh output, never from a rescan.
    advisory_notice_matches: u64,
    /// v3 W2 #6: since when this run has held wakes (a modal question on its
    /// screen or a provider error), and whether that hold was already
    /// surfaced as "blocked but active". Reset when the hold ends.
    hold_since: Option<Instant>,
    hold_alerted: bool,
    /// v3 W2 #6: this member's latest own room post, message or card.
    last_room_post_at: Option<Instant>,
    /// v3 J4: this run's latest turn ended with this structured provider error
    /// (from the member's own rollout, set and cleared by the reconciler).
    provider_error: Option<String>,
    /// v3 W2: the member's own rollout shows this run's latest turn still open
    /// (presentation only: a quiet exec-cell screen is not idle).
    rollout_turn_open: bool,
    work_error_observations: HashMap<String, Vec<Instant>>,
    running: Option<RunningSession>,
    output_draining: bool,
    /// When the exact-Job check first reported this run's agent exited (F2):
    /// the drain grace counts from that evidence, never from a wrapper's exit.
    agent_exited_at: Option<Instant>,
    run_id: Option<Uuid>,
    last_run_id: Option<Uuid>,
    bracketed_paste: BracketedPasteRunState,
    codex_work_state: driver_codex::WorkStateTracker,
    grok_startup: driver_grok::StartupTracker,
    room_composer: room_composer::RoomComposer,
    /// v3 W2: the harness CLI version this run's launch program reported,
    /// once observed; None is unknown.
    harness_version: Option<String>,
    grok_initial_idle_pending: bool,
    run_event_sequence: u64,
    generation: SessionGeneration,
    spawn_in_flight: Option<SpawnReservation>,
    lifecycle_operation: Option<LifecycleOperation>,
    stop_intent: Option<StopIntent>,
    termination_uncertain: bool,
    process_id: Option<u32>,
    last_activity_at: Option<String>,
    last_real_output_at: Option<Instant>,
    last_route_from_session_at: Option<String>,
    last_route_from_session_instant: Option<Instant>,
    last_error: Option<String>,
    quiesce_timer: Option<QuiesceTimer>,
    stall_state_entered_at: Option<Instant>,
    stall_state_entered_timestamp: Option<String>,
    stall_detector: Option<StallDetector>,
    /// Harness-side conversation id of the newest run — what Launch resumes.
    /// Minted for Claude/Grok. Codex remains unresolved without launch proof.
    harness_session_id: Option<String>,
    recovery: Option<RecoveryReference>,
    recovery_history: Vec<RecoveryReference>,
    /// Persisted restart eligibility: set while a run is active, cleared on
    /// confirmed same-process retirement, retained when app shutdown interrupts
    /// it. Room restart selection remains independent configuration.
    running_at_shutdown: bool,
    /// Exact saved identity eligible for this boot only; manual actions consume it.
    boot_resume_id: Option<String>,
    /// Last terminal size the UI fitted this pane to; the next run's PTY
    /// spawns at it.
    last_pty_size: Option<(u16, u16)>,
    /// Control-stripped tail of the active run's output (≤ RUN_OUTPUT_TAIL_MAX
    /// bytes). It is what the operator gets to read when the run dies.
    run_output_tail: String,
    /// When the active run was spawned; a harness binary newer than this
    /// changed underneath the run (Grok self-updates in place).
    run_started_at: Option<std::time::SystemTime>,
    /// The stored conversation id the active run was asked to resume, if any.
    run_resume_id: Option<String>,
    /// The program the active run was spawned from.
    run_program: Option<PathBuf>,
    /// For a Terminal pane: the harness last found running inside it, so the
    /// system log announces a detection once per run, not once per message.
    terminal_harness_announced: Option<DriverKind>,
    /// Operator grants beyond the member's own room (A109).
    permissions: MemberPermissions,
    /// A110: the managing member's request that created it, if one did.
    created_by: Option<MemberCreation>,
}

impl SessionSlot {
    fn snapshot(&self) -> SessionSnapshot {
        // v3 W2: an open turn in the member's own rollout is busy even while
        // its screen is quiet (a background exec cell); presentation only.
        let observed = self.running.is_some() && self.work_state_observed;
        let from_record = observed && self.rollout_turn_open && self.work_state == WorkState::Idle;
        // v3 W2 #4 (Reviewer ded940b6): an expired advisory notice is not a
        // current state: no work state and no blocked reason are exported
        // for it; the driver's latch and detail stay internal evidence.
        let observed = observed && expired_advisory_since(self).is_none();
        SessionSnapshot {
            session_id: self.session_id,
            alias: self.definition.alias.clone(),
            label: self.definition.label.clone(),
            driver: self.definition.driver,
            permission_profile: self.definition.permission_profile,
            codex_transport: self.definition.codex_transport,
            launch_choices: self.launch_choices.clone(),
            last_launch: self.last_launch.clone(),
            recovery: self.recovery.as_ref().map(RecoveryReference::snapshot),
            recovery_history: self.recovery_history.iter().map(RecoveryReference::snapshot).collect(),
            lifecycle_state: self.state,
            working_dir: self.definition.working_dir.clone(),
            generation: self.generation,
            run_id: self.run_id,
            run_event_sequence: self.run_event_sequence,
            pty_size: Some(self.last_pty_size.unwrap_or(shared_types::DEFAULT_PTY_SIZE)),
            process_id: self.process_id,
            running: self.running.is_some(),
            output_draining: self.output_draining && self.running.is_some(),
            crash_respawn_waiting: self.crash_respawn_waiting,
            last_activity_at: self.last_activity_at.clone(),
            last_error: self.last_error.clone(),
            last_error_kind: executable_not_found_kind(self.last_error.as_deref()),
            resume_available: self.harness_session_id.is_some() && self.recovery.is_none(),
            was_running_at_shutdown: self.running_at_shutdown,
            permissions: self.permissions,
            blocked_reason: snapshot_blocked_reason(self),
            work_state: observed.then_some(if from_record { WorkState::Thinking } else { self.work_state }),
            work_state_from_record: from_record,
            app_server: self.running.as_ref().and_then(|running| running.app_server.as_ref())
                .map(codex_app_server::Dispatcher::follow),
        }
    }

    fn title(&self) -> &str {
        &self.definition.label
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct QualifiedWorkingDirectory {
    #[serde(default)]
    namespace: WorkingDirectoryNamespace,
    canonical_path: String,
    identity: String,
}

#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
enum WorkingDirectoryNamespace {
    #[default]
    Windows,
    WslUbuntu,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct PersistedSessionV1 {
    session_id: SessionId,
    label: String,
    driver: DriverKind,
    working_directory: QualifiedWorkingDirectory,
    permission_profile: shared_types::PermissionProfile,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    launch_choices: Option<SessionLaunchChoices>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    last_launch: Option<SessionLaunchRecord>,
    #[serde(default)]
    harness_session_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    recovery: Option<RecoveryReference>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    recovery_history: Vec<RecoveryReference>,
    #[serde(default)]
    running_at_shutdown: bool,
    #[serde(default)]
    last_pty_cols: Option<u16>,
    #[serde(default)]
    last_pty_rows: Option<u16>,
    /// Omitted while no grant is set, so older catalogs and rows stay as written.
    #[serde(default, skip_serializing_if = "MemberPermissions::is_default")]
    permissions: MemberPermissions,
    /// A110: the managing member and request that created this session; a
    /// retry of that request finds it here instead of creating another.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    created_by: Option<MemberCreation>,
    /// v3 W4: omitted while `Pty`. A v2 build refuses a row that has it
    /// (unknown field), so rollback-runtime.ps1 stops on it first (W7).
    #[serde(default, skip_serializing_if = "shared_types::CodexTransport::is_pty")]
    codex_transport: shared_types::CodexTransport,
}

/// Who created a session through `member_create`, under which request_id,
/// and the SHA-256 of that create's arguments, which a retry must repeat.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct MemberCreation {
    session_id: SessionId,
    request_id: String,
    /// Empty in a row written before it was recorded; such a row matches no
    /// retry.
    #[serde(default)]
    fingerprint: String,
}

impl MemberCreation {
    /// The same caller and request_id, whatever the arguments.
    fn same_request(&self, other: &Self) -> bool {
        self.session_id == other.session_id && self.request_id == other.request_id
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct SessionCatalogV1 {
    schema_version: u32,
    workspace_preference: QualifiedWorkingDirectory,
    sessions: Vec<PersistedSessionV1>,
    /// A108: per personal repository, what this install's register writer
    /// last wrote (or was about to write) for each member's file.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    register_acks: BTreeMap<String, BTreeMap<SessionId, session_ledger::RegisterAck>>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    recovery_automation: BTreeMap<SessionId, recovery_automation::RecoveryAutomation>,
}

impl SessionCatalogV1 {
    fn empty(workspace_preference: QualifiedWorkingDirectory) -> Self {
        Self {
            schema_version: SESSION_CATALOG_SCHEMA_VERSION,
            workspace_preference,
            sessions: Vec::new(),
            register_acks: BTreeMap::new(),
            recovery_automation: BTreeMap::new(),
        }
    }
}

#[derive(Default)]
struct SessionRegistry {
    by_id: HashMap<SessionId, SessionSlot>,
    order: Vec<SessionId>,
    alias_to_id: HashMap<String, SessionId>,
}

impl SessionRegistry {
    fn from_catalog(catalog: &SessionCatalogV1) -> Result<Self> {
        let mut registry = Self::default();
        let mut conversation_owners: HashMap<(DriverKind, String), Vec<SessionId>> = HashMap::new();
        for persisted in &catalog.sessions {
            if matches!(persisted.driver, DriverKind::Claude | DriverKind::Codex | DriverKind::Grok)
                && let Some(id) = persisted.harness_session_id.as_deref()
            {
                // Normalize UUID spelling for comparison only. Retain the exact
                // imported reference; never rewrite it or select the first owner.
                let key = Uuid::parse_str(id).map(|id| id.to_string()).unwrap_or_else(|_| id.into());
                conversation_owners.entry((persisted.driver, key)).or_default().push(persisted.session_id);
            }
        }
        for persisted in &catalog.sessions {
            if registry.by_id.contains_key(&persisted.session_id) {
                return Err(anyhow!(
                    "session catalog contains duplicate session id '{}'",
                    persisted.session_id
                ));
            }
            validate_session_label(&persisted.label)?;
            if matches!(
                persisted.driver,
                DriverKind::GenericTerminal | DriverKind::Prime
            ) && persisted.permission_profile == shared_types::PermissionProfile::Unsafe
            {
                return Err(anyhow!(
                    "{:?} session '{}' cannot use the unsafe permission profile",
                    persisted.driver,
                    persisted.session_id,
                ));
            }
            validate_driver_working_directory_pair(persisted.driver, &persisted.working_directory)?;
            validate_codex_transport(persisted.driver, persisted.codex_transport)?;
            let definition = SessionDefinition {
                session_id: persisted.session_id,
                alias: session_alias(persisted.session_id),
                label: persisted.label.clone(),
                driver: persisted.driver,
                working_dir: persisted.working_directory.canonical_path.clone(),
                permission_profile: persisted.permission_profile,
                codex_transport: persisted.codex_transport,
            };
            let mut slot = closed_session_slot(definition);
            if let Some(choices) = &persisted.launch_choices {
                session::validate_launch_choices(persisted.driver, choices)?;
                slot.launch_choices = choices.clone();
            }
            slot.qualified_working_directory = Some(persisted.working_directory.clone());
            slot.last_launch = persisted.last_launch.clone();
            slot.harness_session_id = persisted.harness_session_id.clone();
            slot.recovery_history = persisted.recovery_history.clone();
            slot.recovery = persisted.recovery.clone().or_else(|| {
                (persisted.driver == DriverKind::Codex
                    && (persisted.harness_session_id.is_some() || persisted.running_at_shutdown))
                    .then(|| {
                        RecoveryReference::unresolved_codex(
                            persisted.harness_session_id.clone(),
                            true,
                        )
                    })
            });
            if let Some(original_id) = persisted.harness_session_id.as_ref() {
                let key = Uuid::parse_str(original_id).map(|id| id.to_string()).unwrap_or_else(|_| original_id.clone());
                if let Some(owners) = conversation_owners.get(&(persisted.driver, key)).filter(|owners| owners.len() > 1) {
                    let duplicate = RecoveryReference::duplicate_catalog_identity(original_id.clone(), owners);
                    if let Some(previous) = slot.recovery.take()
                        && previous != duplicate
                    {
                        slot.recovery_history.push(previous);
                    }
                    slot.recovery = Some(duplicate);
                }
            }
            slot.running_at_shutdown = persisted.running_at_shutdown;
            slot.boot_resume_id = persisted.running_at_shutdown.then(|| persisted.harness_session_id.clone()).flatten();
            slot.permissions = persisted.permissions;
            slot.created_by = persisted.created_by.clone();
            slot.last_pty_size = persisted
                .last_pty_cols
                .zip(persisted.last_pty_rows)
                .filter(|(cols, rows)| *cols > 0 && *rows > 0);
            registry.insert(slot)?;
        }
        Ok(registry)
    }

    fn insert(&mut self, slot: SessionSlot) -> Result<()> {
        self.validate_insert(&slot)?;
        self.insert_prevalidated(slot);
        Ok(())
    }

    fn validate_insert(&self, slot: &SessionSlot) -> Result<()> {
        let session_id = slot.session_id;
        if self.by_id.contains_key(&session_id) {
            return Err(anyhow!("duplicate session id '{session_id}'"));
        }
        let alias = &slot.definition.alias;
        if self.alias_to_id.contains_key(alias) {
            return Err(anyhow!("duplicate internal session alias '{alias}'"));
        }
        Ok(())
    }

    fn insert_prevalidated(&mut self, slot: SessionSlot) {
        debug_assert!(self.validate_insert(&slot).is_ok());
        let session_id = slot.session_id;
        let alias = slot.definition.alias.clone();
        self.alias_to_id.insert(alias, session_id);
        self.order.push(session_id);
        self.by_id.insert(session_id, slot);
    }

    fn get_by_id(&self, session_id: SessionId) -> Option<&SessionSlot> {
        self.by_id.get(&session_id)
    }

    fn get_by_id_mut(&mut self, session_id: SessionId) -> Option<&mut SessionSlot> {
        self.by_id.get_mut(&session_id)
    }

    fn get_by_alias(&self, alias: &str) -> Option<&SessionSlot> {
        self.alias_to_id
            .get(alias)
            .and_then(|session_id| self.by_id.get(session_id))
    }

    fn remove(&mut self, session_id: SessionId) -> Option<SessionSlot> {
        let slot = self.by_id.remove(&session_id)?;
        self.alias_to_id.remove(&slot.definition.alias);
        self.order.retain(|candidate| *candidate != session_id);
        Some(slot)
    }

    fn ordered_slots(&self) -> impl Iterator<Item = &SessionSlot> {
        self.order
            .iter()
            .filter_map(|session_id| self.by_id.get(session_id))
    }

    fn ordered_snapshots(&self) -> Vec<SessionSnapshot> {
        self.ordered_slots().map(SessionSlot::snapshot).collect()
    }

    #[cfg(test)]
    fn get(&self, alias_or_legacy_label: &str) -> Option<&SessionSlot> {
        if let Some(slot) = self.get_by_alias(alias_or_legacy_label) {
            return Some(slot);
        }
        let mut matches = self.ordered_slots().filter(|slot| {
            slot.definition
                .label
                .eq_ignore_ascii_case(alias_or_legacy_label)
        });
        let only = matches.next()?;
        matches.next().is_none().then_some(only)
    }

    #[cfg(test)]
    fn get_mut(&mut self, alias_or_legacy_label: &str) -> Option<&mut SessionSlot> {
        let session_id = if let Some(session_id) = self.alias_to_id.get(alias_or_legacy_label) {
            *session_id
        } else {
            let mut matches = self.order.iter().copied().filter(|session_id| {
                self.by_id.get(session_id).is_some_and(|slot| {
                    slot.definition
                        .label
                        .eq_ignore_ascii_case(alias_or_legacy_label)
                })
            });
            let only = matches.next()?;
            if matches.next().is_some() {
                return None;
            }
            only
        };
        self.by_id.get_mut(&session_id)
    }

    #[cfg(test)]
    fn values(&self) -> impl Iterator<Item = &SessionSlot> {
        self.ordered_slots()
    }
}

fn session_alias(session_id: SessionId) -> String {
    format!("session-{session_id}")
}

fn validate_session_label(label: &str) -> Result<()> {
    let trimmed = label.trim();
    if trimmed.is_empty() {
        return Err(anyhow!("session label cannot be empty"));
    }
    if trimmed != label {
        return Err(anyhow!(
            "session label cannot contain leading or trailing whitespace"
        ));
    }
    if trimmed.chars().count() > SESSION_LABEL_MAX_CHARS {
        return Err(anyhow!(
            "session label cannot exceed {SESSION_LABEL_MAX_CHARS} characters"
        ));
    }
    if trimmed.chars().any(|character| character.is_control()) {
        return Err(anyhow!("session label cannot contain control characters"));
    }
    Ok(())
}

fn ensure_closed_for_definition_edit(slot: &SessionSlot) -> Result<()> {
    if slot.state != LifecycleState::Closed
        || slot.running.is_some()
        || slot.run_id.is_some()
        || slot.spawn_in_flight.is_some()
        || slot.lifecycle_operation.is_some()
        || slot.stop_intent.is_some()
        || slot.termination_uncertain
    {
        return Err(anyhow!(
            "session '{}' must be fully closed before this operation",
            slot.session_id
        ));
    }
    Ok(())
}

fn next_run_event_identity(slot: &mut SessionSlot, run_id: Uuid) -> RunEventIdentity {
    slot.run_event_sequence = slot
        .run_event_sequence
        .checked_add(1)
        .expect("run event capacity must be reserved before slot mutation");
    RunEventIdentity {
        session_id: slot.session_id,
        run_id,
        generation: slot.generation,
        sequence: slot.run_event_sequence,
    }
}

fn ensure_run_event_capacity(slot: &SessionSlot, required: u64) -> Result<()> {
    slot.run_event_sequence
        .checked_add(required)
        .map(|_| ())
        .ok_or_else(|| {
            anyhow!(
                "run event sequence exhausted for '{}'",
                slot.definition.alias
            )
        })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SessionExitClassification {
    exit_code: Option<i32>,
    signal: Option<i32>,
    success: bool,
    reason: SessionExitReason,
    requested: bool,
    last_error: Option<String>,
}

impl SessionExitClassification {
    fn requested(
        intent: StopIntent,
        exit_code: Option<i32>,
        signal: Option<i32>,
    ) -> SessionExitClassification {
        let reason = match intent.kind {
            StopIntentKind::Operator => SessionExitReason::OperatorStop,
            StopIntentKind::Restart => SessionExitReason::RestartStop,
        };

        SessionExitClassification {
            exit_code,
            signal,
            success: true,
            reason,
            requested: true,
            last_error: None,
        }
    }
}

fn classify_session_exit(
    status: Option<PtyExitStatus>,
    poll_error: Option<String>,
    stop_intent: Option<StopIntent>,
    fallback_reason: SessionExitReason,
    fallback_error: &str,
) -> SessionExitClassification {
    let exit_code = status
        .as_ref()
        .and_then(|status| exit_code_i32(status.exit_code));
    let signal = status
        .as_ref()
        .and_then(|status| parse_exit_signal(status.signal.as_deref()));

    if let Some(intent) = stop_intent {
        return SessionExitClassification::requested(intent, exit_code, signal);
    }

    if let Some(status) = status {
        let has_signal_indicator = status
            .signal
            .as_ref()
            .map(|signal| !signal.trim().is_empty())
            .unwrap_or(false);
        let success = status.success && !has_signal_indicator;
        let reason = if success {
            SessionExitReason::CleanExit
        } else {
            SessionExitReason::CrashExit
        };

        return SessionExitClassification {
            exit_code,
            signal,
            success,
            reason,
            requested: false,
            last_error: session_exit_last_error(reason, exit_code, signal, poll_error.as_deref()),
        };
    }

    SessionExitClassification {
        exit_code: None,
        signal: None,
        success: false,
        reason: fallback_reason,
        requested: false,
        last_error: session_exit_last_error(
            fallback_reason,
            None,
            None,
            poll_error.as_deref().or(Some(fallback_error)),
        ),
    }
}

fn classify_pty_error_exit(
    error: &str,
    stop_intent: Option<StopIntent>,
) -> SessionExitClassification {
    if let Some(intent) = stop_intent {
        return SessionExitClassification::requested(intent, None, None);
    }

    SessionExitClassification {
        exit_code: None,
        signal: None,
        success: false,
        reason: SessionExitReason::PtyError,
        requested: false,
        last_error: Some(error.to_string()),
    }
}

fn exit_code_i32(exit_code: u32) -> Option<i32> {
    i32::try_from(exit_code).ok()
}

fn parse_exit_signal(signal: Option<&str>) -> Option<i32> {
    let raw = signal?.trim();
    if raw.is_empty() {
        return None;
    }
    if let Ok(value) = raw.parse::<i32>() {
        return Some(value);
    }

    let normalized = raw
        .trim_start_matches("SIG")
        .trim_start_matches("sig")
        .to_ascii_uppercase();
    match normalized.as_str() {
        "HUP" => Some(1),
        "INT" => Some(2),
        "QUIT" => Some(3),
        "ILL" => Some(4),
        "TRAP" => Some(5),
        "ABRT" | "IOT" => Some(6),
        "BUS" => Some(7),
        "FPE" => Some(8),
        "KILL" => Some(9),
        "USR1" => Some(10),
        "SEGV" => Some(11),
        "USR2" => Some(12),
        "PIPE" => Some(13),
        "ALRM" => Some(14),
        "TERM" => Some(15),
        _ => None,
    }
}

fn session_exit_last_error(
    reason: SessionExitReason,
    exit_code: Option<i32>,
    signal: Option<i32>,
    detail: Option<&str>,
) -> Option<String> {
    match reason {
        SessionExitReason::CrashExit => {
            if let Some(signal) = signal {
                Some(format!("process exited after signal {signal}"))
            } else if let Some(exit_code) = exit_code {
                Some(format!("process exited with code {exit_code}"))
            } else {
                Some("process exited unsuccessfully".into())
            }
        }
        SessionExitReason::PtyError | SessionExitReason::ProcessDisappeared => Some(
            detail
                .unwrap_or("process exit state unavailable")
                .to_string(),
        ),
        SessionExitReason::CleanExit
        | SessionExitReason::OperatorStop
        | SessionExitReason::RestartStop => None,
    }
}

fn session_exit_event(
    session: String,
    identity: RunEventIdentity,
    process_id: Option<u32>,
    classification: &SessionExitClassification,
    timestamp: String,
) -> RuntimeEvent {
    RuntimeEvent::SessionExit {
        identity,
        session,
        process_id,
        exit_code: classification.exit_code,
        signal: classification.signal,
        success: classification.success,
        reason: classification.reason,
        requested: classification.requested,
        timestamp,
    }
}

