    #[test]
    fn grok_minimal_framing_rejects_cr_and_unmeasured_size_or_line_count() {
        // The minimal framing contract, tested directly: Grok panes ship the
        // fullscreen TUI now and map to BracketedPaste.
        let behavior = SubmitBehavior {
            sequence: "\r",
            framing: MessageFraming::GrokMinimal,
            submit_delay: BRACKETED_PASTE_SUBMIT_DELAY,
        };
        assert_eq!(
            validate_message_framing("first\r\nsecond", behavior)
                .unwrap_err()
                .to_string(),
            "Grok minimal delivery supports LF line boundaries only; carriage returns are not admitted"
        );
        validate_message_framing(&"x".repeat(GROK_MINIMAL_BODY_MAX_BYTES), behavior).unwrap();
        assert_eq!(
            validate_message_framing(&"x".repeat(GROK_MINIMAL_BODY_MAX_BYTES + 1), behavior)
                .unwrap_err()
                .to_string(),
            format!(
                "Grok minimal delivery body is {} bytes; measured maximum is {GROK_MINIMAL_BODY_MAX_BYTES} bytes",
                GROK_MINIMAL_BODY_MAX_BYTES + 1
            )
        );
        validate_message_framing(&"\n".repeat(GROK_MINIMAL_BODY_MAX_LINES - 1), behavior).unwrap();
        let excessive = "\n".repeat(GROK_MINIMAL_BODY_MAX_LINES);
        assert_eq!(
            validate_message_framing(&excessive, behavior)
                .unwrap_err()
                .to_string(),
            format!(
                "Grok minimal delivery has {} source lines; measured maximum is {GROK_MINIMAL_BODY_MAX_LINES}",
                GROK_MINIMAL_BODY_MAX_LINES + 1
            )
        );
    }

    #[test]
    fn message_validation_is_bounded_and_fail_closed() {
        validate_message_body(&"x".repeat(MESSAGE_BODY_MAX_BYTES)).unwrap();

        let too_large = "x".repeat(MESSAGE_BODY_MAX_BYTES + 1);
        assert_eq!(
            validate_message_body(&too_large).unwrap_err().to_string(),
            format!(
                "message body is {} bytes; maximum is {} bytes",
                MESSAGE_BODY_MAX_BYTES + 1,
                MESSAGE_BODY_MAX_BYTES
            )
        );
        let multibyte_too_large = "é".repeat(MESSAGE_BODY_MAX_BYTES / 2 + 1);
        assert!(multibyte_too_large.chars().count() < MESSAGE_BODY_MAX_BYTES);
        assert_eq!(multibyte_too_large.len(), MESSAGE_BODY_MAX_BYTES + 2);
        assert!(
            validate_message_body(&multibyte_too_large)
                .unwrap_err()
                .to_string()
                .contains(&format!("maximum is {MESSAGE_BODY_MAX_BYTES} bytes"))
        );
        assert_eq!(
            validate_message_body("before\x1b[201~after")
                .unwrap_err()
                .to_string(),
            "message body contains disallowed control character U+001B at byte offset 6"
        );
        assert_eq!(
            validate_message_body("before\0after")
                .unwrap_err()
                .to_string(),
            "message body contains disallowed control character U+0000 at byte offset 6"
        );
        assert_eq!(
            validate_message_body("before\x03after")
                .unwrap_err()
                .to_string(),
            "message body contains disallowed control character U+0003 at byte offset 6"
        );
        assert_eq!(
            validate_message_body("before\x7fafter")
                .unwrap_err()
                .to_string(),
            "message body contains disallowed control character U+007F at byte offset 6"
        );
        assert_eq!(
            validate_message_body("before\u{009b}after")
                .unwrap_err()
                .to_string(),
            "message body contains disallowed control character U+009B at byte offset 6"
        );
    }

