    #[cfg(windows)]
    struct KillWindowsChild(std::process::Child);

    #[cfg(windows)]
    impl Drop for KillWindowsChild {
        fn drop(&mut self) {
            let _ = self.0.kill();
            let _ = self.0.wait();
        }
    }

    #[cfg(windows)]
    struct WindowsJobBackedPty {
        job: pty_host::ProcessJob,
        process_id: u32,
    }

    #[cfg(windows)]
    impl PtySessionTrait for WindowsJobBackedPty {
        fn send_input(&self, input: &str) -> pty_host::PtyWriteResult {
            Ok(input.len())
        }

        fn resize(&self, _cols: u16, _rows: u16) -> Result<()> {
            Ok(())
        }

        fn kill(&self) -> Result<()> {
            self.job.terminate()
        }

        fn try_wait(&self) -> Result<Option<pty_host::PtyExitStatus>> {
            Ok(None)
        }

        fn process_id(&self) -> Option<u32> {
            Some(self.process_id)
        }

        fn contains_process(&self, process: &pty_host::PinnedProcess) -> Result<bool> {
            self.job.contains_process(process)
        }
    }

    #[cfg(windows)]
    struct BlockingWindowsJobPty {
        job: pty_host::ProcessJob,
        process_id: u32,
        entered: Mutex<Option<mpsc::Sender<()>>>,
        release: Arc<(Mutex<bool>, Condvar)>,
        killed: Arc<AtomicBool>,
    }

    #[cfg(windows)]
    struct NonReleasingBlockingWindowsJobPty {
        job: pty_host::ProcessJob,
        process_id: u32,
        entered: Mutex<Option<mpsc::Sender<()>>>,
        release: Arc<(Mutex<bool>, Condvar)>,
        kill_count: Arc<AtomicUsize>,
    }

    #[cfg(windows)]
    impl PtySessionTrait for BlockingWindowsJobPty {
        fn send_input(&self, _input: &str) -> pty_host::PtyWriteResult {
            if let Some(entered) = self.entered.lock().take() {
                let _ = entered.send(());
            }
            let (released, signal) = &*self.release;
            let mut released = released.lock();
            while !*released {
                signal.wait(&mut released);
            }
            Err(PtyWriteError::new(
                0,
                "blocking PTY write interrupted by shutdown",
            ))
        }

        fn resize(&self, _cols: u16, _rows: u16) -> Result<()> {
            Ok(())
        }

        fn kill(&self) -> Result<()> {
            self.killed.store(true, Ordering::SeqCst);
            let (released, signal) = &*self.release;
            *released.lock() = true;
            signal.notify_all();
            self.job.terminate()
        }

        fn try_wait(&self) -> Result<Option<pty_host::PtyExitStatus>> {
            Ok(None)
        }

        fn process_id(&self) -> Option<u32> {
            Some(self.process_id)
        }

        fn contains_process(&self, process: &pty_host::PinnedProcess) -> Result<bool> {
            self.job.contains_process(process)
        }
    }

    #[cfg(windows)]
    impl PtySessionTrait for NonReleasingBlockingWindowsJobPty {
        fn send_input(&self, _input: &str) -> pty_host::PtyWriteResult {
            if let Some(entered) = self.entered.lock().take() {
                let _ = entered.send(());
            }
            let (released, signal) = &*self.release;
            let mut released = released.lock();
            while !*released {
                signal.wait(&mut released);
            }
            Err(PtyWriteError::new(
                0,
                "blocking PTY write released after bounded shutdown",
            ))
        }

        fn resize(&self, _cols: u16, _rows: u16) -> Result<()> {
            Ok(())
        }

        fn kill(&self) -> Result<()> {
            if self.kill_count.fetch_add(1, Ordering::SeqCst) == 0 {
                return Err(anyhow!(
                    "injected process-scope termination failure without writer release"
                ));
            }
            self.job.terminate()
        }

        fn try_wait(&self) -> Result<Option<pty_host::PtyExitStatus>> {
            Ok(None)
        }

        fn process_id(&self) -> Option<u32> {
            Some(self.process_id)
        }

        fn contains_process(&self, process: &pty_host::PinnedProcess) -> Result<bool> {
            self.job.contains_process(process)
        }
    }

    #[cfg(windows)]
    fn windows_test_pipe_endpoint(label: &str) -> String {
        format!(
            r"\\.\pipe\prim1-{label}-{}-{}",
            std::process::id(),
            Uuid::new_v4()
        )
    }

    #[cfg(windows)]
    fn windows_pipe_name(endpoint: &str) -> &str {
        endpoint
            .strip_prefix(r"\\.\pipe\")
            .expect("test endpoint must be a local Windows pipe")
    }

    #[cfg(windows)]
    fn powershell_single_quoted(value: &str) -> String {
        value.replace('\'', "''")
    }

    #[cfg(windows)]
    fn spawn_pipe_client_that_waits(endpoint: &str) -> KillWindowsChild {
        let script = format!(
            "$client = [System.IO.Pipes.NamedPipeClientStream]::new('.', '{}', [System.IO.Pipes.PipeDirection]::InOut); \
             $client.Connect(5000); \
             Start-Sleep -Seconds 60",
            powershell_single_quoted(windows_pipe_name(endpoint)),
        );
        std::process::Command::new("powershell")
            .args(["-NoProfile", "-NonInteractive", "-Command"])
            .arg(script)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .map(KillWindowsChild)
            .expect("spawn real Windows pipe client")
    }

    #[cfg(windows)]
    #[test]
    fn windows_named_pipe_reports_kernel_client_process_id_and_exit() {
        let endpoint = windows_test_pipe_endpoint("caller-pid");
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_io()
            .enable_time()
            .build()
            .expect("build pipe test runtime");
        let server = runtime.block_on(async {
            create_windows_pipe_server(&endpoint, true).expect("create real named-pipe server")
        });
        let mut child = spawn_pipe_client_that_waits(&endpoint);
        runtime.block_on(async {
            tokio::time::timeout(Duration::from_secs(5), server.connect())
                .await
                .expect("real pipe client did not connect")
                .expect("connect real pipe client");
        });

        let process = pane_process_from_windows_pipe(&server)
            .expect("derive caller from GetNamedPipeClientProcessId");
        assert_eq!(process.pid(), child.0.id());
        assert!(process.is_alive().expect("query live pipe caller"));

        child.0.kill().expect("kill real pipe client");
        child.0.wait().expect("wait for real pipe client exit");
        assert!(!process.is_alive().expect("query exited pipe caller"));

        let supervisor = test_supervisor();
        let error = supervisor
            .resolve_pane_caller(process)
            .err()
            .expect("exited pipe caller must be rejected");
        assert!(error.to_string().contains("has exited"), "{error:#}");
    }

    #[cfg(windows)]
    #[test]
    fn unaffiliated_named_pipe_client_is_refused_after_its_frame_and_admitted_by_the_pane_secret() {
        use tokio::io::AsyncWriteExt as _;

        let supervisor = test_supervisor();
        let (pty, _inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "claude",
            DriverKind::Claude,
            pty,
        );
        let secret = mint_pane_secret();
        set_test_pane_secret(&supervisor, "claude", &secret);
        let endpoint = windows_test_pipe_endpoint("unaffiliated");
        let status = supervisor
            .start_control_plane_at(Some(endpoint))
            .expect("start real control plane");
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_io()
            .enable_time()
            .build()
            .expect("build pipe client runtime");

        let exchange = |lines: Vec<String>| {
            let endpoint = status.endpoint.clone();
            runtime.block_on(async move {
                // The server re-creates its pipe instance after each client;
                // under a loaded parallel suite the next connect can arrive
                // first (ERROR_PIPE_BUSY 231 or ERROR_FILE_NOT_FOUND 2).
                let connect_deadline = Instant::now() + Duration::from_secs(5);
                let mut client = loop {
                    match tokio::net::windows::named_pipe::ClientOptions::new().open(&endpoint) {
                        Ok(client) => break client,
                        Err(error)
                            if matches!(error.raw_os_error(), Some(231) | Some(2))
                                && Instant::now() < connect_deadline =>
                        {
                            tokio::time::sleep(Duration::from_millis(10)).await;
                        }
                        Err(error) => panic!("connect unaffiliated client: {error}"),
                    }
                };
                for line in lines {
                    client
                        .write_all(format!("{line}\n").as_bytes())
                        .await
                        .expect("write frame");
                }
                client.flush().await.expect("flush frames");
                let mut reader = BufReader::new(client);
                let mut response_line = String::new();
                tokio::time::timeout(Duration::from_secs(5), reader.read_line(&mut response_line))
                    .await
                    .expect("server answered the frame")
                    .expect("read response");
                decode_response(response_line.trim()).expect("decode response")
            })
        };
        let ping = encode_request(&SidebandRequest::Ping {}).unwrap();

        // No preamble: this test process is in no pane job → refused, after its frame.
        let denied = exchange(vec![ping.clone()]);
        assert!(!denied.ok);
        assert_eq!(denied.message, "sideband access denied");

        // A wrong secret is refused the same way.
        let wrong = exchange(vec![
            control_plane::encode_preamble(&shared_types::SidebandPreamble {
                secret: "not-the-secret".into(),
            })
            .unwrap(),
            ping.clone(),
        ]);
        assert!(!wrong.ok);
        assert_eq!(wrong.message, "sideband access denied");

        // The pane's own secret admits the same process as that pane.
        let admitted = exchange(vec![
            control_plane::encode_preamble(&shared_types::SidebandPreamble {
                secret: secret.clone(),
            })
            .unwrap(),
            ping,
        ]);
        assert!(admitted.ok, "{}", admitted.message);
        assert_eq!(admitted.message, "pong");

        let audit = fs::read_to_string(supervisor.audit_log_path()).unwrap();
        assert!(
            !audit.contains(&secret),
            "the pane secret leaked into the audit log"
        );
        supervisor.shutdown().expect("stop real control plane");
    }

    fn set_test_pane_secret(supervisor: &SupervisorHandle, name: &str, secret: &str) {
        let session_id = test_session_id(supervisor, name);
        let mut slots = supervisor.inner.slots.lock();
        slots
            .get_by_id_mut(session_id)
            .expect("test session")
            .running
            .as_mut()
            .expect("test session must be running")
            .pane_secret = Some(secret.to_string());
    }

    #[test]
    fn secret_identity_binds_to_one_live_run_and_expires_with_it() {
        let supervisor = test_supervisor();
        let (claude_pty, _claude_inputs) = recording_pty_session(std::process::id());
        let (codex_pty, _codex_inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "claude",
            DriverKind::Claude,
            claude_pty,
        );
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "codex",
            DriverKind::Codex,
            codex_pty,
        );
        let claude = test_session_id(&supervisor, "claude");
        let codex = test_session_id(&supervisor, "codex");
        let claude_secret = mint_pane_secret();
        let codex_secret = mint_pane_secret();
        set_test_pane_secret(&supervisor, "claude", &claude_secret);
        set_test_pane_secret(&supervisor, "codex", &codex_secret);

        assert!(supervisor.resolve_pane_caller_by_secret("").is_err());
        let unknown = supervisor
            .resolve_pane_caller_by_secret("0000")
            .err()
            .expect("an unknown secret must not resolve");
        assert!(
            unknown.to_string().contains("matches no live pane"),
            "{unknown}"
        );
        let caller = supervisor
            .resolve_pane_caller_by_secret(&claude_secret)
            .expect("the live secret resolves");
        assert_eq!(caller.session_id, claude);
        assert!(matches!(caller.identity, PaneCallerIdentity::Secret(_)));
        assert_eq!(
            supervisor
                .resolve_pane_caller_by_secret(&codex_secret)
                .unwrap()
                .session_id,
            codex
        );

        supervisor
            .create_room(CreateRoomRequest {
                brief_on_join: true,
                brief_template: None,
                label: Some("Secret room".into()),
                member_ids: vec![claude, codex],
            })
            .unwrap();
        let posted = supervisor.apply_sideband_request(
            &caller,
            SidebandRequest::RoomPost {
                request_id: None,
                content: "posted via the pane secret".into(),
            },
        );
        assert!(posted.ok, "{}", posted.message);
        let read =
            supervisor.apply_sideband_request(&caller, SidebandRequest::RoomRead { owed_after: None, cursor: None, expect_room: None });
        let Some(SidebandResponsePayload::RoomFeed { page }) = read.payload else {
            panic!("missing feed page")
        };
        assert!(page.events.iter().any(|event| matches!(
            &event.item,
            RoomFeedItem::Message { sender: RoomMessageSender::Session { session_id }, content, .. }
                if *session_id == claude && content == "posted via the pane secret"
        )));
        assert_eq!(page.members.len(), 2);
        assert!(page.members.iter().any(|member| member.session_id == claude
            && member.driver == DriverKind::Claude
            && member.label == "claude"));

        // A new run mints a new secret: the old caller is stale.
        set_test_pane_secret(&supervisor, "claude", &mint_pane_secret());
        let stale = supervisor.apply_sideband_request(&caller, SidebandRequest::Ping {});
        assert!(!stale.ok);
        assert!(stale.message.contains("stale"), "{}", stale.message);
        assert!(
            supervisor
                .resolve_pane_caller_by_secret(&claude_secret)
                .is_err()
        );

        let audit = fs::read_to_string(supervisor.audit_log_path()).unwrap();
        assert!(!audit.contains(&claude_secret));
        assert!(!audit.contains(&codex_secret));
    }

    #[test]
    fn sideband_stream_admits_a_preamble_secret_without_a_job_caller() {
        use tokio::io::AsyncWriteExt as _;

        let supervisor = test_supervisor();
        let (pty, _inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "claude",
            DriverKind::Claude,
            pty,
        );
        let secret = mint_pane_secret();
        set_test_pane_secret(&supervisor, "claude", &secret);
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_io()
            .enable_time()
            .build()
            .unwrap();
        let exchange = |lines: Vec<String>| {
            let handle = supervisor.clone();
            runtime.block_on(async move {
                let (mut client, server) = tokio::io::duplex(16 * 1024);
                let server_task =
                    tokio::spawn(async move { handle_sideband_stream(handle, JobAttribution::Outside(0), server).await });
                for line in lines {
                    client
                        .write_all(format!("{line}\n").as_bytes())
                        .await
                        .unwrap();
                }
                client.flush().await.unwrap();
                let mut reader = BufReader::new(client);
                let mut response_line = String::new();
                tokio::time::timeout(Duration::from_secs(5), reader.read_line(&mut response_line))
                    .await
                    .unwrap()
                    .unwrap();
                server_task.await.unwrap().unwrap();
                decode_response(response_line.trim()).unwrap()
            })
        };
        let ping = encode_request(&SidebandRequest::Ping {}).unwrap();
        let preamble = |secret: &str| {
            control_plane::encode_preamble(&shared_types::SidebandPreamble {
                secret: secret.into(),
            })
            .unwrap()
        };

        let denied = exchange(vec![ping.clone()]);
        assert!(!denied.ok);
        assert_eq!(denied.message, "sideband access denied");
        let wrong = exchange(vec![preamble("wrong"), ping.clone()]);
        assert!(!wrong.ok);
        let admitted = exchange(vec![preamble(&secret), ping]);
        assert!(admitted.ok, "{}", admitted.message);
        assert_eq!(admitted.message, "pong");
    }

    #[test]
    fn pane_room_deliver_wakes_members_with_the_pane_label_and_never_itself() {
        let supervisor = test_supervisor();
        // Liveness prunes runs whose OS pid is dead: the caller pane borrows this
        // test process's pid; the recipient keeps no pid (never pruned).
        let live_pid = std::process::id();
        let (claude_pty, claude_inputs) = recording_pty_session(live_pid);
        let (codex_pty, codex_inputs) = recording_pty_session(102);
        install_mock_running_session_with_process_id_and_bracketed_paste_enabled(
            &supervisor,
            "claude",
            DriverKind::Claude,
            Some(live_pid),
            claude_pty,
        );
        install_mock_room_wake_recipient(&supervisor, "codex", codex_pty,
        );
        let claude = test_session_id(&supervisor, "claude");
        let codex = test_session_id(&supervisor, "codex");
        let room = supervisor
            .create_room(CreateRoomRequest {
                brief_on_join: true,
                brief_template: None,
                label: Some("Wake room".into()),
                member_ids: vec![claude, codex],
            })
            .unwrap();
        let caller = supervisor
            .resolve_pane_caller(TestPaneProcess::new(9001, [live_pid]))
            .unwrap();

        let delivered = supervisor.apply_sideband_request(
            &caller,
            SidebandRequest::RoomDeliver {
                request_id: None,
                recipient: "codex".into(),
                content: "wake up, I need your output".into(),
            },
        );
        assert!(delivered.ok, "{}", delivered.message);
        let Some(SidebandResponsePayload::RoomDelivery { result }) = delivered.payload else {
            panic!("missing delivery payload")
        };
        assert_eq!(result.recipient_count, 1);
        assert_eq!(result.written_count, 1);
        assert!(result.failures.is_empty());
        // v3 W3: the wake is a content-neutral pointer; the calling pane's
        // label reaches the recipient through the stored sender (checked in
        // the feed below), never through PRIM-1's paste.
        assert_eq!(
            *codex_inputs.lock(),
            vec![typed_pointer(&supervisor, 1, result.message_id), "\r".to_string()]
        );
        assert!(
            claude_inputs.lock().is_empty(),
            "the sender's own terminal stays untouched"
        );

        let by_id = supervisor.apply_sideband_request(
            &caller,
            SidebandRequest::RoomDeliver {
                request_id: None,
                recipient: codex.to_string(),
                content: "by id".into(),
            },
        );
        assert!(by_id.ok, "{}", by_id.message);
        let Some(SidebandResponsePayload::RoomDelivery { result: by_id_result }) = by_id.payload else {
            panic!("missing by-id delivery payload")
        };
        let to_self = supervisor.apply_sideband_request(
            &caller,
            SidebandRequest::RoomDeliver {
                request_id: None,
                recipient: claude.to_string(),
                content: "hello me".into(),
            },
        );
        assert!(!to_self.ok);
        assert!(
            to_self.message.contains("calling pane itself"),
            "{}",
            to_self.message
        );
        let nobody = supervisor.apply_sideband_request(
            &caller,
            SidebandRequest::RoomDeliver {
                request_id: None,
                recipient: "hermes".into(),
                content: "anyone?".into(),
            },
        );
        assert!(!nobody.ok);
        assert!(
            nobody.message.contains("no other room member is labelled"),
            "{}",
            nobody.message
        );
        let all = supervisor.apply_sideband_request(
            &caller,
            SidebandRequest::RoomDeliver {
                request_id: None,
                recipient: "ALL".into(),
                content: "everyone but me".into(),
            },
        );
        assert!(all.ok, "{}", all.message);
        let Some(SidebandResponsePayload::RoomDelivery { result: all_result }) = all.payload else {
            panic!("missing all-delivery payload")
        };
        assert_eq!(all_result.recipient_count, 1, "all excludes the caller");
        assert!(claude_inputs.lock().is_empty());
        assert_eq!(codex_inputs.lock().len(), 6);
        // Each pointer counts every message codex has neither read nor ACKed.
        assert_eq!(codex_inputs.lock()[2], typed_pointer(&supervisor, 2, by_id_result.message_id));
        assert_eq!(codex_inputs.lock()[4], typed_pointer(&supervisor, 3, all_result.message_id));
        assert!(codex_inputs.lock().iter().all(|input| !input.contains("claude") && !input.contains("everyone")));

        let page = supervisor
            .read_room_feed(ReadRoomFeedRequest {
                room_id: room.room_id,
                cursor: None,
            })
            .unwrap();
        assert!(page.events.iter().any(|event| matches!(
            &event.item,
            RoomFeedItem::Message { sender: RoomMessageSender::Session { session_id }, recipient_ids, content, .. }
                if *session_id == claude && recipient_ids == &vec![codex] && content == "wake up, I need your output"
        )));
        assert_eq!(
            page.events
                .iter()
                .filter(|event| matches!(
                    event.item,
                    RoomFeedItem::Delivery { status: RoomDeliveryStatus::Written, recipient_id, .. }
                        if recipient_id == codex
                ))
                .count(),
            3
        );
        assert_eq!(page.members.len(), 2);
    }

    fn set_submit_verify_tuning(supervisor: &SupervisorHandle, window: Duration, attempts: usize) {
        *supervisor.inner.delivery_timing_tuning.lock() =
            Some((Duration::ZERO, Duration::ZERO, window, attempts));
    }

    #[test]
    fn a_swallowed_submit_is_retried_until_the_pane_responds_or_attempts_end() {
        let supervisor = test_supervisor();
        set_submit_verify_tuning(&supervisor, Duration::from_millis(120), 3);
        let (pty, inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "claude",
            DriverKind::Claude,
            pty,
        );
        route_operator_to_test_session(&supervisor, "claude", "big feedback body")
            .expect("delivery should succeed");
        let written = inputs.lock().clone();
        assert_eq!(
            written.iter().filter(|input| input.as_str() == "\r").count(),
            3,
            "a pane that never responds gets every submit attempt: {written:?}"
        );
        assert!(
            written[0].contains("big feedback body"),
            "payload precedes the submits"
        );
    }

    struct ArgRecordingPtySpawner {
        args: Arc<Mutex<Vec<Vec<String>>>>,
        sessions: Mutex<Vec<Box<dyn PtySessionTrait>>>,
    }

    impl PtySpawner for ArgRecordingPtySpawner {
        fn spawn(
            &self,
            plan: &PreparedLaunch,
            _handler: PtyEventHandler,
        ) -> Result<Box<dyn PtySessionTrait>> {
            self.args.lock().push(plan.spec.args.clone());
            self.sessions
                .lock()
                .pop()
                .ok_or_else(|| anyhow!("capturing spawner exhausted"))
        }
    }

    #[test]
    fn launch_mints_persists_and_resumes_the_harness_conversation_id() {
        let root = std::env::temp_dir().join(format!("prim1-resume-{}", Uuid::new_v4()));
        fs::create_dir_all(root.join("work")).unwrap();
        let captured = Arc::new(Mutex::new(Vec::new()));
        let first_id;
        {
            let supervisor = SupervisorHandle::new(test_supervisor_config(&root)).unwrap();
            supervisor.set_executable_resolver_for_tests(Arc::new(TestExecutableResolver));
            install_standard_test_sessions(&supervisor);
            let claude = test_session_id(&supervisor, "claude");
            let (pty, _inputs) = recording_pty_session(std::process::id());
            supervisor.set_pty_spawner_for_tests(Arc::new(ArgRecordingPtySpawner {
                args: Arc::clone(&captured),
                sessions: Mutex::new(vec![pty]),
            }));
            start_test_session(&supervisor, "claude").unwrap();
            let args = captured.lock().last().unwrap().clone();
            let position = args
                .iter()
                .position(|arg| arg == "--session-id")
                .expect("a fresh Claude launch pins --session-id");
            first_id = args[position + 1].clone();
            {
                let slots = supervisor.inner.slots.lock();
                let slot = slots.get_by_id(claude).unwrap();
                assert_eq!(slot.harness_session_id.as_deref(), Some(first_id.as_str()));
                assert!(slot.running_at_shutdown);
                assert!(slot.snapshot().resume_available);
            }
            supervisor
                .resize_session_by_id(claude, 190, 45)
                .expect("resize the running session");
            supervisor.stop_session_by_id(claude).unwrap();
            assert!(
                !supervisor
                    .inner
                    .slots
                    .lock()
                    .get_by_id(claude)
                    .unwrap()
                    .running_at_shutdown,
                "an operator stop clears the workspace-relaunch flag"
            );
            supervisor.shutdown().unwrap();
        }

        // Restart: the id reloads; Launch resumes it; fresh mints anew.
        let supervisor = SupervisorHandle::new(test_supervisor_config(&root)).unwrap();
        supervisor.set_executable_resolver_for_tests(Arc::new(TestExecutableResolver));
        let claude = test_session_id(&supervisor, "claude");
        assert_eq!(
            supervisor
                .inner
                .slots
                .lock()
                .get_by_id(claude)
                .unwrap()
                .harness_session_id
                .as_deref(),
            Some(first_id.as_str()),
            "the conversation id survives the app restart"
        );
        assert_eq!(
            supervisor
                .inner
                .slots
                .lock()
                .get_by_id(claude)
                .unwrap()
                .last_pty_size,
            Some((190, 45)),
            "the pane size survives the app restart and seeds the next spawn"
        );
        let (pty, _inputs) = recording_pty_session(std::process::id());
        let (second_pty, _second_inputs) = recording_pty_session(std::process::id());
        supervisor.set_pty_spawner_for_tests(Arc::new(ArgRecordingPtySpawner {
            args: Arc::clone(&captured),
            sessions: Mutex::new(vec![second_pty, pty]),
        }));
        start_test_session(&supervisor, "claude").unwrap();
        let resume_args = captured.lock().last().unwrap().clone();
        assert!(
            resume_args
                .iter()
                .any(|arg| *arg == format!("--resume={first_id}")),
            "{resume_args:?}"
        );
        supervisor.stop_session_by_id(claude).unwrap();
        supervisor
            .start_session_by_id_with_mode(claude, true)
            .unwrap();
        let fresh_args = captured.lock().last().unwrap().clone();
        let position = fresh_args
            .iter()
            .position(|arg| arg == "--session-id")
            .expect("a fresh relaunch mints a new id");
        assert_ne!(fresh_args[position + 1], first_id);
    }

    #[test]
    fn render_room_brief_substitutes_an_edited_template_and_one_lines_it_for_terminals() {
        let claude = RoomMember {
            session_id: Uuid::new_v4(),
            label: "CC".into(),
            driver: DriverKind::Claude,
        };
        let terminal = RoomMember {
            session_id: Uuid::new_v4(),
            label: "Shell".into(),
            driver: DriverKind::GenericTerminal,
        };
        let members = vec![claude.clone(), terminal.clone()];
        let template =
            "Hello {your_label} of {room_label}.\r\nOthers: {members}.\r\nTools: {tools}";

        let for_claude = render_room_brief("Edited", &members, &claude, MemberPermissions::default(), None, Some(template));
        assert!(for_claude.contains("Hello CC of Edited."), "{for_claude}");
        assert!(
            for_claude.contains("Others: Shell (Terminal)."),
            "{for_claude}"
        );
        assert!(for_claude.contains("prim1_pane MCP server"), "{for_claude}");
        assert!(!for_claude.contains('\r'), "{for_claude}");
        assert!(!for_claude.contains("Do not reach the pipe"), "{for_claude}");

        let for_terminal = render_room_brief("Edited", &members, &terminal, MemberPermissions::default(), None, Some(template));
        assert!(!for_terminal.contains('\n'), "{for_terminal}");
        assert!(
            for_terminal.contains("Hello Shell of Edited. · Others: CC (Claude Code)."),
            "{for_terminal}"
        );
    }

    #[test]
    fn room_brief_template_normalization_trims_bounds_and_defaults() {
        assert_eq!(normalize_room_brief_template(None).unwrap(), None);
        assert_eq!(
            normalize_room_brief_template(Some("  \r\n \n ".into())).unwrap(),
            None
        );
        assert_eq!(
            normalize_room_brief_template(Some("  keep\r\nboth lines \n".into())).unwrap(),
            Some("keep\nboth lines".into())
        );
        let oversized = "x".repeat(ROOM_BRIEF_TEMPLATE_MAX_BYTES + 1);
        let error = normalize_room_brief_template(Some(oversized)).unwrap_err();
        assert!(error.to_string().contains("maximum is"), "{error}");
        // A request that omits the new fields keeps the old behaviour.
        let request: CreateRoomRequest = serde_json::from_str(r#"{"member_ids":[]}"#).unwrap();
        assert!(request.brief_on_join);
        assert!(request.brief_template.is_none());
    }

    #[test]
    fn render_room_brief_is_one_line_for_terminals_and_names_the_tools_per_driver() {
        let claude = RoomMember {
            session_id: Uuid::new_v4(),
            label: "CC".into(),
            driver: DriverKind::Claude,
        };
        let grok = RoomMember {
            session_id: Uuid::new_v4(),
            label: "Grok".into(),
            driver: DriverKind::Grok,
        };
        let terminal = RoomMember {
            session_id: Uuid::new_v4(),
            label: "Shell".into(),
            driver: DriverKind::GenericTerminal,
        };
        let members = vec![claude.clone(), grok.clone(), terminal.clone()];
        let cli = Path::new(r"C:\PRIM-1\prim1.exe");

        let for_claude = render_room_brief("Team A", &members, &claude, MemberPermissions::default(), Some(cli), None);
        assert!(for_claude.contains("prim1_pane MCP server"));
        assert!(for_claude.contains("Grok (Grok Build), Shell (Terminal)"));
        assert!(
            !for_claude.contains("CC (Claude Code)"),
            "the member is not listed to itself"
        );
        assert!(for_claude.contains('\n'));

        let for_grok = render_room_brief("Team A", &members, &grok, MemberPermissions::default(), Some(cli), None);
        assert!(for_grok.contains(r"C:\PRIM-1\prim1.exe"));
        assert!(for_grok.contains("--prim1-room ping"));

        let for_terminal = render_room_brief("Team A", &members, &terminal, MemberPermissions::default(), None, None);
        assert!(
            !for_terminal.contains('\n'),
            "terminal framing admits a single line"
        );
        assert!(for_terminal.contains("$env:PRIM1_CLI"));
        assert!(
            validate_message_framing(
                &for_terminal,
                routed_message_submit_behavior(DriverKind::GenericTerminal)
            )
            .is_ok()
        );
        assert!(
            validate_message_framing(&for_grok, routed_message_submit_behavior(DriverKind::Grok))
                .is_ok()
        );
    }

    #[cfg(windows)]
    #[test]
    fn job_assigned_named_pipe_child_is_accepted_end_to_end() {
        use std::io::Write as _;

        let root = tempfile::tempdir().expect("create assigned-client test root");
        let supervisor = test_supervisor_with_root(root.path().to_path_buf());
        let endpoint = windows_test_pipe_endpoint("assigned");
        let status = supervisor
            .start_control_plane_at(Some(endpoint))
            .expect("start real control plane");
        let response_path = root.path().join("assigned-response.json");
        let request = encode_request(&SidebandRequest::Ping {}).expect("encode ping request");
        let script = format!(
            "[void][Console]::In.ReadLine(); \
             $client = [System.IO.Pipes.NamedPipeClientStream]::new('.', '{}', [System.IO.Pipes.PipeDirection]::InOut); \
             $client.Connect(5000); \
             $writer = [System.IO.StreamWriter]::new($client); \
             $writer.AutoFlush = $true; \
             $writer.WriteLine('{}'); \
             $reader = [System.IO.StreamReader]::new($client); \
             $response = $reader.ReadLine(); \
             [System.IO.File]::WriteAllText('{}', $response)",
            powershell_single_quoted(windows_pipe_name(&status.endpoint)),
            powershell_single_quoted(&request),
            powershell_single_quoted(&response_path.display().to_string()),
        );
        let mut child = std::process::Command::new("powershell")
            .args(["-NoProfile", "-NonInteractive", "-Command"])
            .arg(script)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .map(KillWindowsChild)
            .expect("spawn assigned pipe child");
        let process_id = child.0.id();
        let mut release = child.0.stdin.take().expect("capture assigned child stdin");
        let job = pty_host::ProcessJob::new().expect("create assigned child job");
        let pinned_child = PinnedProcess::open(process_id).expect("pin assigned pipe child");
        job.assign_process(&pinned_child)
            .expect("assign pipe child to session job");
        install_mock_running_session_with_process_id(
            &supervisor,
            "claude",
            DriverKind::Claude,
            Some(process_id),
            Box::new(WindowsJobBackedPty { job, process_id }),
        );
        release
            .write_all(b"connect\n")
            .expect("release assigned pipe child");
        release.flush().expect("flush assigned child gate");
        drop(release);

        let deadline = Instant::now() + Duration::from_secs(8);
        let response_text = loop {
            match fs::read_to_string(&response_path) {
                Ok(response) if !response.is_empty() => break response,
                Ok(_) | Err(_) if Instant::now() < deadline => {
                    thread::sleep(Duration::from_millis(20));
                }
                Ok(_) | Err(_) => panic!("assigned pipe child did not receive a response"),
            }
        };
        let response = decode_response(&response_text).expect("decode assigned child response");
        assert!(response.ok, "assigned child was rejected: {response:?}");
        assert_eq!(response.message, "pong");

        supervisor
            .shutdown()
            .expect("stop assigned-client supervisor");
    }

    #[cfg(windows)]
    #[test]
    fn shutdown_interrupts_authorized_blocking_pipe_write_before_listener_join() {
        use std::io::Write as _;

        let root = tempfile::tempdir().expect("create blocking-write test root");
        let supervisor = test_supervisor_with_root(root.path().to_path_buf());
        let endpoint = windows_test_pipe_endpoint("blocking-write");
        let status = supervisor
            .start_control_plane_at(Some(endpoint.clone()))
            .expect("start blocking-write control plane");
        let claude_alias = test_session_alias(&supervisor, "claude");
        let request = encode_request(&SidebandRequest::SendInput {
            name: claude_alias,
            input: "force blocking PTY write".into(),
        })
        .expect("encode blocking input request");
        let script = format!(
            "[void][Console]::In.ReadLine(); \
             $client = [System.IO.Pipes.NamedPipeClientStream]::new('.', '{}', [System.IO.Pipes.PipeDirection]::InOut); \
             $client.Connect(5000); \
             $writer = [System.IO.StreamWriter]::new($client); \
             $writer.AutoFlush = $true; \
             $writer.WriteLine('{}'); \
             $reader = [System.IO.StreamReader]::new($client); \
             [void]$reader.ReadLine()",
            powershell_single_quoted(windows_pipe_name(&status.endpoint)),
            powershell_single_quoted(&request),
        );
        let mut child = std::process::Command::new("powershell")
            .args(["-NoProfile", "-NonInteractive", "-Command"])
            .arg(script)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .map(KillWindowsChild)
            .expect("spawn blocking pipe child");
        let process_id = child.0.id();
        let mut release_child = child.0.stdin.take().expect("capture child gate");
        let job = pty_host::ProcessJob::new().expect("create blocking child job");
        let pinned_child = PinnedProcess::open(process_id).expect("pin blocking pipe child");
        job.assign_process(&pinned_child)
            .expect("assign blocking child to session job");
        let (entered_tx, entered_rx) = mpsc::channel();
        let release_write = Arc::new((Mutex::new(false), Condvar::new()));
        let killed = Arc::new(AtomicBool::new(false));
        install_mock_running_session_with_process_id(
            &supervisor,
            "claude",
            DriverKind::Claude,
            Some(process_id),
            Box::new(BlockingWindowsJobPty {
                job,
                process_id,
                entered: Mutex::new(Some(entered_tx)),
                release: release_write.clone(),
                killed: killed.clone(),
            }),
        );
        release_child
            .write_all(b"connect\n")
            .expect("release blocking pipe child");
        release_child.flush().expect("flush child gate");
        drop(release_child);
        entered_rx
            .recv_timeout(Duration::from_secs(5))
            .expect("authorized sideband request never entered the blocking PTY write");

        let shutdown_supervisor = supervisor.clone();
        let (done_tx, done_rx) = mpsc::channel();
        let shutdown = thread::spawn(move || {
            let _ = done_tx.send(shutdown_supervisor.shutdown());
        });
        let shutdown_result = done_rx
            .recv_timeout(Duration::from_secs(3))
            .unwrap_or_else(|_| {
                let (released, signal) = &*release_write;
                *released.lock() = true;
                signal.notify_all();
                panic!("shutdown did not interrupt the blocked PTY write before listener join")
            });
        shutdown_result.expect("shutdown after blocking write failed");
        shutdown.join().expect("shutdown thread panicked");
        assert!(killed.load(Ordering::SeqCst));

        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_io()
            .build()
            .expect("build replacement pipe runtime");
        runtime.block_on(async {
            let replacement = create_windows_pipe_server(&endpoint, true)
                .expect("control-plane endpoint was not reusable after shutdown");
            drop(replacement);
        });
    }

    #[cfg(windows)]
    #[test]
    fn shutdown_retains_an_unjoined_listener_when_a_pipe_writer_cannot_be_interrupted() {
        use std::io::Write as _;

        let root = tempfile::tempdir().expect("create bounded-listener test root");
        let supervisor = test_supervisor_with_root(root.path().to_path_buf());
        supervisor.set_sideband_write_timeout_for_tests(Duration::from_secs(60));
        supervisor.set_stop_kill_timeout_for_tests(Duration::from_millis(50));
        let session_id = test_session_id(&supervisor, "claude");
        let endpoint = windows_test_pipe_endpoint("bounded-listener-stop");
        let status = supervisor
            .start_control_plane_at(Some(endpoint.clone()))
            .expect("start bounded-listener control plane");
        let claude_alias = test_session_alias(&supervisor, "claude");
        let request = encode_request(&SidebandRequest::SendInput {
            name: claude_alias,
            input: "hold the listener runtime open".into(),
        })
        .expect("encode blocking input request");
        let script = format!(
            "[void][Console]::In.ReadLine(); \
             $client = [System.IO.Pipes.NamedPipeClientStream]::new('.', '{}', [System.IO.Pipes.PipeDirection]::InOut); \
             $client.Connect(5000); \
             $writer = [System.IO.StreamWriter]::new($client); \
             $writer.AutoFlush = $true; \
             $writer.WriteLine('{}'); \
             $reader = [System.IO.StreamReader]::new($client); \
             [void]$reader.ReadLine()",
            powershell_single_quoted(windows_pipe_name(&status.endpoint)),
            powershell_single_quoted(&request),
        );
        let mut child = std::process::Command::new("powershell")
            .args(["-NoProfile", "-NonInteractive", "-Command"])
            .arg(script)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .map(KillWindowsChild)
            .expect("spawn bounded-listener pipe child");
        let process_id = child.0.id();
        let mut release_child = child.0.stdin.take().expect("capture child gate");
        let job = pty_host::ProcessJob::new().expect("create blocking child job");
        let pinned_child = PinnedProcess::open(process_id).expect("pin blocking pipe child");
        job.assign_process(&pinned_child)
            .expect("assign blocking child to session job");
        let (entered_tx, entered_rx) = mpsc::channel();
        let release_write = Arc::new((Mutex::new(false), Condvar::new()));
        let kill_count = Arc::new(AtomicUsize::new(0));
        install_mock_running_session_with_process_id(
            &supervisor,
            "claude",
            DriverKind::Claude,
            Some(process_id),
            Box::new(NonReleasingBlockingWindowsJobPty {
                job,
                process_id,
                entered: Mutex::new(Some(entered_tx)),
                release: release_write.clone(),
                kill_count: kill_count.clone(),
            }),
        );
        release_child
            .write_all(b"connect\n")
            .expect("release blocking pipe child");
        release_child.flush().expect("flush child gate");
        drop(release_child);
        entered_rx
            .recv_timeout(Duration::from_secs(5))
            .expect("authorized request never entered the non-releasing writer");

        let started = Instant::now();
        let error = supervisor
            .shutdown()
            .expect_err("unproved PTY cleanup and listener join must be reported");
        assert!(
            started.elapsed() < Duration::from_secs(1),
            "shutdown exceeded its bounded listener deadline: {:?}",
            started.elapsed()
        );
        assert!(
            error
                .to_string()
                .contains("control-plane listener did not stop"),
            "unexpected bounded shutdown error: {error:#}"
        );
        assert_eq!(kill_count.load(Ordering::SeqCst), 1);
        assert!(
            supervisor.inner.control_plane_listener.lock().is_some(),
            "a timed-out listener join must retain the exact join handle for retry"
        );

        let (released, signal) = &*release_write;
        *released.lock() = true;
        signal.notify_all();
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let retry_ready = {
                let listener_finished = supervisor
                    .inner
                    .control_plane_listener
                    .lock()
                    .as_ref()
                    .and_then(|listener| listener.thread.as_ref())
                    .is_some_and(thread::JoinHandle::is_finished);
                let lifecycle_clear = supervisor
                    .inner
                    .slots
                    .lock()
                    .get_by_id(session_id)
                    .unwrap()
                    .lifecycle_operation
                    .is_none();
                listener_finished && lifecycle_clear
            };
            if retry_ready {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "released listener or termination worker did not finish"
            );
            thread::sleep(Duration::from_millis(10));
        }

        supervisor.set_stop_kill_timeout_for_tests(Duration::from_secs(2));
        supervisor
            .shutdown()
            .expect("repeated shutdown must join the retained listener and prove termination");
        assert_eq!(kill_count.load(Ordering::SeqCst), 2);
        assert!(supervisor.inner.control_plane_listener.lock().is_none());
        drop(pinned_child);
    }

    #[cfg(windows)]
    #[test]
    fn tokenless_control_plane_start_is_idempotent_and_shutdown_joins_listener() {
        let supervisor = test_supervisor();
        let events = capture_runtime_events(&supervisor);
        let endpoint = windows_test_pipe_endpoint("lifecycle");
        let first = supervisor
            .start_control_plane_at(Some(endpoint.clone()))
            .expect("start tokenless control plane");
        let second = supervisor
            .start_control_plane_at(Some(windows_test_pipe_endpoint("ignored")))
            .expect("repeat tokenless control-plane startup");

        assert_eq!(first, second);
        assert_eq!(
            events
                .lock()
                .iter()
                .filter(|event| matches!(event, RuntimeEvent::ControlPlaneReady { .. }))
                .count(),
            1
        );
        assert!(
            fs::read_dir(supervisor.runtime_dir())
                .expect("read tokenless runtime directory")
                .filter_map(|entry| entry.ok())
                .all(|entry| !entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with("control-plane")),
            "tokenless startup must not recreate bearer files"
        );

        supervisor.shutdown().expect("join control-plane listener");
        assert!(supervisor.snapshot().control_plane.is_none());

        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_io()
            .build()
            .expect("build replacement pipe runtime");
        runtime.block_on(async {
            let replacement = create_windows_pipe_server(&endpoint, true)
                .expect("listener handle survived shutdown join");
            drop(replacement);
        });

        let error = supervisor
            .start_control_plane_at(Some(endpoint))
            .expect_err("terminal supervisor must not restart its listener");
        assert_eq!(error.to_string(), "supervisor has shut down");
        supervisor
            .shutdown()
            .expect("repeated shutdown is idempotent");
    }

    #[cfg(windows)]
    #[test]
    fn control_plane_start_and_shutdown_share_one_terminal_lifecycle_order() {
        let supervisor = test_supervisor();
        let events = capture_runtime_events(&supervisor);
        let endpoint = windows_test_pipe_endpoint("start-shutdown-order");
        let (prepared_tx, prepared_rx) = mpsc::sync_channel(1);
        let (release_tx, release_rx) = mpsc::sync_channel(1);
        *supervisor.inner.control_plane_after_prepare.lock() = Some(Box::new(move || {
            prepared_tx.send(()).unwrap();
            release_rx.recv().unwrap();
        }));

        let start_supervisor = supervisor.clone();
        let start_endpoint = endpoint.clone();
        let start =
            thread::spawn(move || start_supervisor.start_control_plane_at(Some(start_endpoint)));
        prepared_rx
            .recv_timeout(Duration::from_secs(5))
            .expect("control-plane start did not reach the prepared barrier");
        assert!(
            supervisor.inner.shutdown_lifecycle.try_write().is_none(),
            "start must hold the terminal lifecycle lock through listener preparation"
        );

        let shutdown_supervisor = supervisor.clone();
        let (shutdown_invoked_tx, shutdown_invoked_rx) = mpsc::sync_channel(1);
        let (shutdown_done_tx, shutdown_done_rx) = mpsc::sync_channel(1);
        let shutdown = thread::spawn(move || {
            shutdown_invoked_tx.send(()).unwrap();
            shutdown_done_tx
                .send(shutdown_supervisor.shutdown())
                .unwrap();
        });
        shutdown_invoked_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("shutdown thread did not start");
        assert!(
            shutdown_done_rx
                .recv_timeout(Duration::from_millis(100))
                .is_err(),
            "shutdown must not overtake an admitted control-plane start"
        );
        assert!(!supervisor.inner.shutdown_started.load(Ordering::Acquire));

        release_tx.send(()).unwrap();
        let started = start.join().expect("control-plane start thread panicked");
        assert!(started.is_ok(), "admitted start should linearize first");
        shutdown_done_rx
            .recv_timeout(Duration::from_secs(5))
            .expect("shutdown did not complete after start released")
            .expect("shutdown failed");
        shutdown.join().expect("shutdown thread panicked");

        assert!(supervisor.snapshot().control_plane.is_none());
        assert_eq!(
            events
                .lock()
                .iter()
                .filter(|event| matches!(event, RuntimeEvent::ControlPlaneReady { .. }))
                .count(),
            1
        );
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_io()
            .build()
            .expect("build endpoint reuse runtime");
        runtime.block_on(async {
            let replacement = create_windows_pipe_server(&endpoint, true)
                .expect("ordered shutdown must release the prepared endpoint");
            drop(replacement);
        });
    }

