    /// v3 W2 (11 Oct item 1; the inherited test31 red): a question on screen
    /// still refuses routed input before any side effect, while an escalated
    /// notice is advisory and the message is typed.
    #[test]
    fn observed_unsafe_work_state_rejects_synthetic_delivery_before_message_side_effects() {
        let supervisor = test_supervisor();
        let (pty, inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "codex",
            DriverKind::Codex,
            pty,
        );
        set_session_dispatch_state(
            &supervisor,
            "codex",
            LifecycleState::Ready,
            Some(WorkState::Blocked),
        );
        supervisor
            .inner
            .slots
            .lock()
            .get_mut("codex")
            .unwrap()
            .work_detail = Some("workspace_trust".into());
        let before = slots_mutation_probe(&supervisor);
        let audit_before = fs::read(supervisor.audit_log_path()).unwrap_or_default();
        let events = capture_runtime_events(&supervisor);
        let session_id = test_session_id(&supervisor, "codex");

        let error = supervisor
            .route_operator_message(OperatorRouteMessageRequest {
                recipient_id: session_id,
                content: "must not enter a modal prompt".into(),
            })
            .unwrap_err();
        let text = error.to_string();
        assert!(text.contains("work state is blocked (modal:workspace_trust)"), "{error:#}");
        assert!(
            text.starts_with("Nothing was delivered. codex (")
                && text.contains(") can't take a routed message right now: "),
            "operator-legible lead: {error:#}"
        );
        assert!(
            text.contains("it is asking whether to trust the folder — answer that question in its terminal, then send again."),
            "{error:#}"
        );
        assert!(
            !text.contains("use raw terminal input to resolve the prompt"),
            "the old instruction did not clear notices and is gone: {error:#}"
        );
        assert_eq!(slots_mutation_probe(&supervisor), before);
        assert!(inputs.lock().is_empty());
        assert!(events.lock().is_empty());
        assert_eq!(
            fs::read(supervisor.audit_log_path()).unwrap_or_default(),
            audit_before
        );

        // The same pane with an escalated usage-cap notice instead: advisory,
        // so the routed message is typed.
        set_session_dispatch_state(
            &supervisor,
            "codex",
            LifecycleState::Ready,
            Some(WorkState::ErrorLoop),
        );
        supervisor
            .inner
            .slots
            .lock()
            .get_mut("codex")
            .unwrap()
            .work_detail = Some("rate_limit".into());
        supervisor
            .route_operator_message(OperatorRouteMessageRequest {
                recipient_id: session_id,
                content: "an advisory notice never refuses".into(),
            })
            .expect("a notice is advisory status, not a refusal");
        assert!(!inputs.lock().is_empty(), "the message was typed");
    }

    #[test]
    fn codex_workspace_trust_blocks_route_then_raw_resolution_allows_the_first_clean_route() {
        let supervisor = test_supervisor();
        let codex_alias = test_session_alias(&supervisor, "codex");
        let (pty, inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "codex",
            DriverKind::Codex,
            pty,
        );
        let events = capture_runtime_events(&supervisor);

        handle_current_pty_event(
            &supervisor,
            "codex",
            0,
            PtyEvent::Output(
                "Do you trust the contents of this directory?\n› 1. Yes, continue\n  2. No, exit\nPress enter to continue"
                    .into(),
            ),
        );

        assert!(work_state_events(&events).iter().any(|event| matches!(
            event,
            RuntimeEvent::SessionWorkState {
                session,
                state: WorkState::Blocked,
                detail: Some(detail),
                ..
            } if session == &codex_alias && detail == "workspace_trust"
        )));
        events.lock().clear();
        let before = slots_mutation_probe(&supervisor);
        let audit_before = fs::read(supervisor.audit_log_path()).unwrap_or_default();

        let session_id = test_session_id(&supervisor, "codex");
        let error = supervisor
            .route_operator_message(OperatorRouteMessageRequest {
                recipient_id: session_id,
                content: "do not type into trust UI".into(),
            })
            .unwrap_err();

        assert!(
            error
                .to_string()
                .contains("work state is blocked (modal:workspace_trust)"),
            "{error:#}"
        );
        assert_eq!(slots_mutation_probe(&supervisor), before);
        assert!(inputs.lock().is_empty());
        assert!(events.lock().is_empty());
        assert_eq!(
            fs::read(supervisor.audit_log_path()).unwrap_or_default(),
            audit_before
        );

        supervisor
            .send_input(SendInputRequest {
                session_id,
                input: "1\r".into(),
            })
            .expect("raw operator input must remain available to resolve the modal");
        supervisor
            .resize_session_by_id(session_id, 196, 22)
            .expect("match the measured e16a viewport");
        handle_current_pty_event(
            &supervisor,
            "codex",
            0,
            PtyEvent::Output(codex_clean_prompt_stream()),
        );
        {
            let slots = supervisor.inner.slots.lock();
            let slot = slots.get_by_id(session_id).unwrap();
            assert_eq!(slot.work_state, WorkState::Idle);
            assert!(!slot.codex_work_state.is_blocked());
        }

        supervisor
            .route_operator_message(OperatorRouteMessageRequest {
                recipient_id: session_id,
                content: "first route after raw modal resolution".into(),
            })
            .expect("the trusted blocker-free screen must admit the first synthetic route");
        assert_eq!(
            inputs.lock().len(),
            3,
            "one raw resolution write plus payload and submit writes"
        );
    }

    #[test]
    fn missing_catalog_persists_zero_sessions_and_explicit_empty_reopens_empty() {
        let root = tempfile::tempdir().expect("create zero-session catalog root");
        let supervisor = empty_test_supervisor_with_root(root.path().to_path_buf());
        assert!(supervisor.snapshot().sessions.is_empty());

        let catalog_path = session_catalog_path(supervisor.runtime_dir());
        let first_bytes = fs::read(&catalog_path).expect("read initial empty catalog");
        let first_catalog: serde_json::Value =
            serde_json::from_slice(&first_bytes).expect("parse initial empty catalog");
        assert_eq!(first_catalog["schema_version"], 1);
        assert_eq!(first_catalog["sessions"], serde_json::json!([]));
        drop(supervisor);

        let reopened = SupervisorHandle::new(test_supervisor_config(root.path()))
            .expect("reopen explicit empty catalog");
        assert!(reopened.snapshot().sessions.is_empty());
        assert_eq!(
            fs::read(&catalog_path).expect("read reopened empty catalog"),
            first_bytes,
            "an explicit empty catalog must not be reseeded or rewritten"
        );
    }

