    #[test]
    fn feed_only_room_post_writes_no_pty_and_redacts_durable_content() {
        let supervisor = test_supervisor();
        let (claude_pty, claude_inputs) = recording_pty_session(std::process::id());
        let (codex_pty, codex_inputs) = recording_pty_session(std::process::id());
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "claude",
            DriverKind::Claude,
            claude_pty,
        );
        install_mock_running_session_with_bracketed_paste_enabled(
            &supervisor,
            "codex",
            DriverKind::Codex,
            codex_pty,
        );
        let room = supervisor
            .create_room(CreateRoomRequest {
                brief_on_join: true,
                brief_template: None,
                label: Some("Feed only".into()),
                member_ids: vec![
                    test_session_id(&supervisor, "claude"),
                    test_session_id(&supervisor, "codex"),
                ],
            })
            .unwrap();
        let sentinel = "FEED-ONLY-PRIVATE-λ-🚀";

        let result = supervisor
            .post_room_message(PostRoomMessageRequest {
                request_id: None,
                room_id: room.room_id,
                content: sentinel.into(),
            })
            .unwrap();
        let page = supervisor
            .read_room_feed(ReadRoomFeedRequest {
                room_id: room.room_id,
                cursor: None,
            })
            .unwrap();

        assert_eq!(
            result.message_id,
            match &page.events.last().unwrap().item {
                RoomFeedItem::Message {
                    message_id,
                    content,
                    recipient_ids,
                    ..
                } => {
                    assert_eq!(content, sentinel);
                    assert!(recipient_ids.is_empty());
                    *message_id
                }
                item => panic!("unexpected feed item: {item:?}"),
            }
        );
        assert!(claude_inputs.lock().is_empty());
        assert!(codex_inputs.lock().is_empty());
        let audit = fs::read_to_string(supervisor.audit_log_path()).unwrap();
        assert!(!audit.contains(sentinel));
        assert!(audit.contains("[content omitted]"));
    }

    #[test]
    fn empty_and_single_member_rooms_are_legal_and_solo_send_delivers() {
        let supervisor = test_supervisor();
        // An empty room is a workspace set up before its team arrives.
        let empty = supervisor
            .create_room(CreateRoomRequest {
                brief_on_join: true,
                brief_template: None,
                label: Some("Set up first".into()),
                member_ids: Vec::new(),
            })
            .unwrap();
        assert!(empty.member_ids.is_empty());
        let refusal = supervisor
            .deliver_room_message(DeliverRoomMessageRequest {
                request_id: None,
                room_id: empty.room_id,
                recipients: RoomRecipientSelection::All {},
                content: "anyone home?".into(),
            })
            .unwrap_err()
            .to_string();
        assert!(
            refusal.contains("has no members"),
            "an empty room refuses delivery with the plain reason, got: {refusal}"
        );

        // A single-member room is a team of one: operator Send reaches it.
        let (claude_pty, claude_inputs) = recording_pty_session(std::process::id());
        install_mock_room_wake_recipient(&supervisor, "claude", claude_pty,
        );
        let solo = supervisor
            .create_room(CreateRoomRequest {
                brief_on_join: false,
                brief_template: None,
                label: Some("Solo".into()),
                member_ids: vec![test_session_id(&supervisor, "claude")],
            })
            .unwrap();
        let result = supervisor
            .deliver_room_message(DeliverRoomMessageRequest {
                request_id: None,
                room_id: solo.room_id,
                recipients: RoomRecipientSelection::All {},
                content: "solo delivery".into(),
            })
            .unwrap();
        assert_eq!(result.recipient_count, 1);
        assert_eq!(result.written_count, 1);
        assert!(result.failures.is_empty());
        assert!(!claude_inputs.lock().is_empty());
    }

