        let started = supervisor
            .start_session_by_id(created.session_id)
            .expect("prepare Prime launch");
        assert_eq!(started.lifecycle_state, LifecycleState::Ready);

        let plans = plans.lock();
        assert_eq!(plans.len(), 1);
        let plan = &plans[0];
